﻿﻿﻿﻿// === Storage Manager ===
const Storage = {
  _prefix: "novel_",

  get(key, fallback = null) {
    try {
      const val = localStorage.getItem(this._prefix + key);
      return val !== null ? JSON.parse(val) : fallback;
    } catch { return fallback; }
  },

  set(key, value) {
    try { localStorage.setItem(this._prefix + key, JSON.stringify(value)); } catch {}
  },

  remove(key) {
    try { localStorage.removeItem(this._prefix + key); } catch {}
  },

  // Reading progress: { novelId: { chapter, scrollPos } }
  getProgress(novelId) {
    return this.get("progress_" + novelId, { chapter: 1, scrollPos: 0, scrollRatio: 0 });
  },
  setProgress(novelId, chapter, scrollPos, scrollRatio) {
    this.set("progress_" + novelId, { chapter, scrollPos, scrollRatio: scrollRatio || 0 });
  },

  // Bookmarks: { novelId: [chapterIds] }
  getBookmarks(novelId) {
    return this.get("bookmarks_" + novelId, []);
  },
  toggleBookmark(novelId, chapterId) {
    const bm = this.getBookmarks(novelId);
    const idx = bm.indexOf(chapterId);
    if (idx > -1) bm.splice(idx, 1); else bm.push(chapterId);
    this.set("bookmarks_" + novelId, bm);
    return !bm.includes(chapterId) ? "removed" : "added"; // Return final state
  },
  isBookmarked(novelId, chapterId) {
    return this.getBookmarks(novelId).includes(chapterId);
  },

  // Reader settings
  getSettings() {
    return this.get("settings", {
      fontSize: 18,
      lineHeight: 1.8,
      theme: "light",
      pageMode: "scroll"
    });
  },
  setSettings(settings) {
    this.set("settings", settings);
  },
  // IndexedDB chapter cache (offline support)
  _db: null,
  _dbReady: null,

  _openDB() {
    if (this._dbReady) return this._dbReady;
    this._dbReady = new Promise((resolve, reject) => {
      const req = indexedDB.open("NovelCache", 1);
      req.onupgradeneeded = () => {
        req.result.createObjectStore("chapters", { keyPath: "key" });
      };
      req.onsuccess = () => { this._db = req.result; resolve(); };
      req.onerror = () => { this._dbReady = null; reject(req.error); };
    });
    return this._dbReady;
  },

  async getCachedChapter(novelId, chapterId) {
    try {
      await this._openDB();
      const tx = this._db.transaction("chapters", "readonly");
      const store = tx.objectStore("chapters");
      const data = await new Promise((r) => {
        const req = store.get(novelId + "/" + chapterId);
        req.onsuccess = () => r(req.result ? req.result.content : null);
        req.onerror = () => r(null);
      });
      return data;
    } catch { return null; }
  },

  async cacheChapter(novelId, chapterId, content) {
    try {
      await this._openDB();
      const tx = this._db.transaction("chapters", "readwrite");
      const store = tx.objectStore("chapters");
      store.put({ key: novelId + "/" + chapterId, content: content });
    } catch {}
  }
};
// === Reader Module ===
const Reader = {
  novel: null,
  currentChapter: 1,
  settings: null,

  init() {
    this.settings = Storage.getSettings();
    this.applySettings();
    this.bindEvents();
  },

  bindEvents() {
    document.getElementById("btn-reader-back").onclick = () => {
      this.saveProgress();
      App.showScreen("screen-detail");
    };
    document.getElementById("btn-prev-chapter").onclick = () => this.prevChapter();
    document.getElementById("btn-next-chapter").onclick = () => this.nextChapter();
    document.getElementById("btn-reader-catalog").onclick = () => {
      App.showCatalog(this.novel);
    };
    document.getElementById("btn-reader-settings").onclick = () => this.toggleSettings();
    document.getElementById("btn-close-settings").onclick = () => this.toggleSettings(false);
    document.getElementById("btn-theme-cycle").onclick = () => this.cycleTheme();
    document.getElementById("btn-bookmark").onclick = () => this.toggleBookmark();
    document.getElementById("btn-fs-down").onclick = () => this.adjustFontSize(-1);
    document.getElementById("btn-fs-up").onclick = () => this.adjustFontSize(1);
    document.getElementById("btn-lh-down").onclick = () => this.adjustLineHeight(-0.2);
    document.getElementById("btn-lh-up").onclick = () => this.adjustLineHeight(0.2);
    document.querySelectorAll("#theme-options .theme-btn").forEach(btn => {
      btn.onclick = () => this.setTheme(btn.dataset.theme);
    });
    document.querySelectorAll("#page-mode-options .theme-btn").forEach(btn => {
      btn.onclick = () => this.setPageMode(btn.dataset.mode);
    });

    const overlay = document.createElement("div");
    overlay.className = "settings-overlay";
    overlay.id = "settings-overlay";
    overlay.onclick = () => this.toggleSettings(false);
    document.body.appendChild(overlay);

    // Percentage badge
    let pctEl = document.getElementById("reader-pct");
    if (!pctEl) {
      pctEl = document.createElement("div");
      pctEl.id = "reader-pct";
      pctEl.className = "reader-pct";
      pctEl.textContent = "0%";
      document.getElementById("screen-reader").appendChild(pctEl);
    }

    // Scroll: update pct and hide controls
    const content = document.getElementById("reader-content");
    content.addEventListener("scroll", () => {
      this.onScroll();
      this.hideControls();
    });

    // Touch: detect tap vs scroll
    content.addEventListener("touchstart", (e) => {
      this._tapY = e.touches[0].clientY;
      this._tapMoved = false;
    }, { passive: true });
    content.addEventListener("touchmove", () => {
      this._tapMoved = true;
    }, { passive: true });
    content.addEventListener("touchend", (e) => {
      if (this._tapMoved || this._tapY === undefined) return;
      this._tapY = undefined;
      if (e.target.closest(".reader-header, .reader-footer, .footer-btn, .nav-btn")) return;
      this.toggleControls();
    }, { passive: true });
  },

  open(novel, chapterId = null) {
    this.novel = novel;
    const progress = Storage.getProgress(novel.id);
    this.currentChapter = chapterId || progress.chapter;
    this.renderChapter();
    App.showScreen("screen-reader");
    this.updateNavButtons();
    this.updateBookmarkBtn();
    this.showControls();
    if (!chapterId && progress.scrollPos) {
      setTimeout(() => {
        document.getElementById("reader-content").scrollTop = progress.scrollPos;
      }, 100);
    }
  },

  renderChapter() {
    const ch = this.novel.chapters.find(c => c.id === this.currentChapter);
    if (!ch) return;
    document.getElementById("reader-chapter-title").textContent = ch.title;
    const contentEl = document.getElementById("reader-content");
    if (ch.content) {
      contentEl.innerHTML = "<h3>" + ch.title + "</h3>" + ch.content.replace(/\\n/g, "\n").split("\n").filter(p => p.trim()).map(p => "<p>" + p.trim() + "</p>").join("");
      contentEl.scrollTop = 0;
    } else {
      contentEl.innerHTML = "<div class='catalog-loading' style='padding-top:60px'>加载中...</div>";
      Storage.getCachedChapter(this.novel.id, this.currentChapter).then(cached => {
        if (cached) {
          ch.content = cached.replace(/\\n/g, "\n");
          if (this.currentChapter === ch.id) {
            contentEl.innerHTML = "<h3>" + ch.title + "</h3>" + ch.content.split("\n").filter(p => p.trim()).map(p => "<p>" + p.trim() + "</p>").join("");
            const _sv=Storage.getProgress(this.novel.id);if(_sv&&_sv.scrollPos&&this.currentChapter===_sv.chapter){contentEl.scrollTop=_sv.scrollPos}
          }
          return;
        }
                // Try local server as fallback (for GitHub Pages deployment)
        const tryLocal = (ips) => {
          if (ips.length === 0) {
            if (this.currentChapter === ch.id) contentEl.innerHTML = "<div class='catalog-loading'>请先连接电脑打开服务器</div>";
            return;
          }
          fetch("http://" + ips[0] + ":8080/chapters/" + this.novel.id + "/" + this.currentChapter + ".json")
            .then(r => r.json())
            .then(data => {
              ch.content = data.content.replace(/\\n/g, "\n");
              Storage.cacheChapter(this.novel.id, this.currentChapter, ch.content);
              if (this.currentChapter === data.id) {
                contentEl.innerHTML = "<h3>" + ch.title + "</h3>" + ch.content.split("\n").filter(p => p.trim()).map(p => "<p>" + p.trim() + "</p>").join("");
                var _sv=Storage.getProgress(this.novel.id);if(_sv&&_sv.scrollPos&&this.currentChapter===_sv.chapter){contentEl.scrollTop=_sv.scrollPos}
              }
            })
            .catch(function(){ tryLocal(ips.slice(1)); });
        };
fetch("chapters/" + this.novel.id + "/" + this.currentChapter + ".json")
          .then(r => r.json())
          .then(data => {
            ch.content = data.content.replace(/\\n/g, "\n");
            Storage.cacheChapter(this.novel.id, this.currentChapter, ch.content);
            if (this.currentChapter === data.id) {
              contentEl.innerHTML = "<h3>" + ch.title + "</h3>" + ch.content.split("\n").filter(p => p.trim()).map(p => "<p>" + p.trim() + "</p>").join("");
              const _sv=Storage.getProgress(this.novel.id);if(_sv&&_sv.scrollPos&&this.currentChapter===_sv.chapter){contentEl.scrollTop=_sv.scrollPos}
            }
          })
          .catch(() => {
            tryLocal(["10.60.14.229","10.60.7.184","172.20.10.6","192.168.1.100","localhost"]);
          });
      });
    }
    document.getElementById("progress-fill").style.width = "0%";
    document.getElementById("progress-text").textContent = "0%";
  },

  prevChapter() {
    const idx = this.novel.chapters.findIndex(c => c.id === this.currentChapter);
    if (idx > 0) {
      this.currentChapter = this.novel.chapters[idx - 1].id;
      this.renderChapter();
      this.updateNavButtons();
      this.updateBookmarkBtn();
      this.saveProgress();
    }
  },

  nextChapter() {
    const idx = this.novel.chapters.findIndex(c => c.id === this.currentChapter);
    if (idx < this.novel.chapters.length - 1) {
      this.currentChapter = this.novel.chapters[idx + 1].id;
      this.renderChapter();
      this.updateNavButtons();
      this.updateBookmarkBtn();
      this.saveProgress();
    }
  },

  updateNavButtons() {
    const idx = this.novel.chapters.findIndex(c => c.id === this.currentChapter);
    document.getElementById("btn-prev-chapter").disabled = idx === 0;
    document.getElementById("btn-next-chapter").disabled = idx === this.novel.chapters.length - 1;
  },

  onScroll() {
    const el = document.getElementById("reader-content");
    const pct = Math.min(100, Math.round((el.scrollTop / (el.scrollHeight - el.clientHeight)) * 100));
    document.getElementById("progress-fill").style.width = pct + "%";
    document.getElementById("progress-text").textContent = pct + "%";
    const pctEl = document.getElementById("reader-pct");
    if (pctEl) pctEl.textContent = pct + "%";
  },

  saveProgress() {
    const el = document.getElementById("reader-content");
    const ratio = el.scrollHeight > el.clientHeight ? el.scrollTop / (el.scrollHeight - el.clientHeight) : 0;
    Storage.setProgress(this.novel.id, this.currentChapter, el.scrollTop, ratio);
  },

  toggleSettings(show) {
    const panel = document.getElementById("settings-panel");
    const overlay = document.getElementById("settings-overlay");
    const s = show !== undefined ? show : !panel.classList.contains("show");
    panel.classList.toggle("show", s);
    overlay.classList.toggle("show", s);
    if (s) this.updateSettingsUI();
  },

  updateSettingsUI() {
    document.getElementById("font-size-display").textContent = this.settings.fontSize;
    document.getElementById("line-height-display").textContent = this.settings.lineHeight.toFixed(1);
    document.querySelectorAll("#theme-options .theme-btn").forEach(b => {
      b.classList.toggle("active", b.dataset.theme === this.settings.theme);
    });
    document.querySelectorAll("#page-mode-options .theme-btn").forEach(b => {
      b.classList.toggle("active", b.dataset.mode === this.settings.pageMode);
    });
  },

  adjustFontSize(delta) {
    this.settings.fontSize = Math.max(12, Math.min(28, this.settings.fontSize + delta));
    this.applySettings();
    this.updateSettingsUI();
    Storage.setSettings(this.settings);
  },

  adjustLineHeight(delta) {
    this.settings.lineHeight = Math.max(1.2, Math.min(3.0, +(this.settings.lineHeight + delta).toFixed(1)));
    this.applySettings();
    this.updateSettingsUI();
    Storage.setSettings(this.settings);
  },

  setTheme(theme) {
    this.settings.theme = theme;
    this.applySettings();
    Storage.setSettings(this.settings);
    this.updateSettingsUI();
  },

  setPageMode(mode) {
    this.settings.pageMode = mode;
    Storage.setSettings(this.settings);
    this.updateSettingsUI();
  },

  applySettings() {
    const s = this.settings;
    const content = document.getElementById("reader-content");
    content.style.fontSize = s.fontSize + "px";
    content.style.lineHeight = s.lineHeight;
    const reader = document.getElementById("screen-reader");
    reader.classList.remove("theme-sepia", "theme-dark", "theme-green");
    if (s.theme !== "light") reader.classList.add("theme-" + s.theme);
    this.updateThemeIcon();
  },

  // Immersive controls
  _controlsTimer: null,

  showControls() {
    document.getElementById("screen-reader").classList.add("controls-visible");
    clearTimeout(this._controlsTimer);
    this._controlsTimer = setTimeout(() => this.hideControls(), 3000);
  },

  hideControls() {
    document.getElementById("screen-reader").classList.remove("controls-visible");
  },

  toggleControls() {
    const el = document.getElementById("screen-reader");
    if (el.classList.contains("controls-visible")) {
      this.hideControls();
    } else {
      this.showControls();
    }
  },

  toggleBookmark() {
    if (!this.novel) return;
    const result = Storage.toggleBookmark(this.novel.id, this.currentChapter);
    this.updateBookmarkBtn();
    App.showToast(result === "added" ? "已添加书签" : "已取消书签");
  },

  cycleTheme() {
    var themes = ["light", "sepia", "dark", "green"];
    var icons = { light: "☀", sepia: "🍂", dark: "🌙", green: "🌿" };
    var names = { light: "浅色", sepia: "暖色", dark: "深色", green: "绿色" };
    var cur = themes.indexOf(this.settings.theme);
    var next = themes[(cur + 1) % themes.length];
    this.setTheme(next);
    App.showToast("主题: " + names[next]);
  },

  updateThemeIcon() {
    var icons = { light: "☀", sepia: "🍂", dark: "🌙", green: "🌿" };
    var btn = document.getElementById("btn-theme-cycle");
    if (btn) btn.textContent = icons[this.settings.theme] || "🌙";
  },

  updateBookmarkBtn() {
    const btn = document.getElementById("btn-bookmark");
    if (this.novel && Storage.isBookmarked(this.novel.id, this.currentChapter)) {
      btn.textContent = "🔖";
      btn.style.color = "#ff9500";
    } else {
      btn.textContent = "🔖";
      btn.style.color = "";
    }
  }
};
// === App Controller ===
const App = {
  currentNovel: null,
  catalogNovel: null,
  catalogBatchSize: 200,
  catalogRendered: 0,
  catalogLoading: false,
  catalogSearchQuery: "",
  catalogSearchResults: null,

  init() {
    try {
      Reader.init();
      this.renderLibrary();
      this.bindEvents();
      this.bindCatalogSearch();
      this.showInstallBanner();
    } catch(e) {
      document.getElementById("library-grid").innerHTML = "<div style=\"padding:40px;color:red\">JS\u9519\u8bef: " + e.message + "</div>";
    }
  },

  bindEvents() {
    document.getElementById("btn-settings").onclick = () => this.showToast("\u8bbe\u7f6e\u529f\u80fd\u5f00\u53d1\u4e2d");
    document.getElementById("btn-start-read").onclick = () => this.startReading();
    document.getElementById("btn-catalog").onclick = () => this.showCatalog(this.currentNovel);
    document.getElementById("btn-detail-share").onclick = () => this.shareNovel();
    document.getElementById("btn-install-close").onclick = () => {
      document.getElementById("install-banner").style.display = "none";
    };
    document.getElementById("btn-install").onclick = () => {
      document.getElementById("install-banner").style.display = "none";
      document.getElementById("install-guide").classList.add("show");
    };
    document.getElementById("btn-guide-close").onclick = () => {
      document.getElementById("install-guide").classList.remove("show");
    };

    document.querySelectorAll(".nav-back").forEach(btn => {
      btn.onclick = (e) => {
        const target = e.target.closest(".nav-back").dataset.target;
        if (target === "screen-detail" && this.currentNovel) {
          this.showScreen("screen-detail");
          this.renderDetail(this.currentNovel);
        } else {
          this.showScreen(target);
        }
      };
    });
  },

  bindCatalogSearch() {
    const input = document.getElementById("catalog-search-input");
    const clearBtn = document.getElementById("btn-clear-search");
    
    let debounceTimer;
    input.addEventListener("input", () => {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(() => {
        this.catalogSearchQuery = input.value.trim();
        if (this.catalogSearchQuery) {
          clearBtn.style.display = "block";
          this.performSearch();
        } else {
          clearBtn.style.display = "none";
          this.catalogSearchResults = null;
          this.catalogRendered = 0;
          document.getElementById("catalog-list").innerHTML = "";
          this.loadMoreCatalog();
          this.initCatalogScrollbar();
        }
      }, 200);
    });
    
    clearBtn.onclick = () => {
      input.value = "";
      this.catalogSearchQuery = "";
      clearBtn.style.display = "none";
      this.catalogSearchResults = null;
      this.catalogRendered = 0;
      document.getElementById("catalog-list").innerHTML = "";
      this.loadMoreCatalog();
    };
  },

  performSearch() {
    const novel = this.catalogNovel;
    if (!novel) return;
    
    const q = this.catalogSearchQuery.toLowerCase();
    this.catalogSearchResults = novel.chapters.filter(ch => 
      ch.title.toLowerCase().includes(q) || 
      String(ch.id).includes(q)
    );
    
    this.catalogRendered = 0;
    document.getElementById("catalog-list").innerHTML = "";
    
    if (this.catalogSearchResults.length === 0) {
      const div = document.createElement("div");
      div.className = "catalog-loading";
      div.textContent = "\u672a\u627e\u5230\u5339\u914d\u7ae0\u8282";
      document.getElementById("catalog-list").appendChild(div);
      return;
    }
    
    this.loadMoreCatalog();
  },

  showScreen(id) {
    document.querySelectorAll(".screen").forEach(s => s.classList.remove("active"));
    const screen = document.getElementById(id);
    if (screen) screen.classList.add("active");
    document.getElementById("settings-panel").classList.remove("show");
    const overlay = document.getElementById("settings-overlay");
    if (overlay) overlay.classList.remove("show");
  },

  renderLibrary() {
    const grid = document.getElementById("library-grid");
    grid.innerHTML = Novels.map(novel => {
      const progress = Storage.getProgress(novel.id);
      const total = novel.chapters.length;
      const chProgress = total > 0 ? ((progress.chapter - 1 + (progress.scrollRatio || 0)) / total) * 100 : 0;
      const pct = chProgress.toFixed(2);
      return '<div class="novel-card" onclick="App.openNovel(\'' + novel.id + '\')">' +
        '<div class="novel-cover" style="background:' + novel.coverGradient + '">' +
        '<span class="cover-text">' + novel.title + '</span></div>' +
        '<div class="novel-info"><div class="novel-title">' + novel.title + '</div>' +
        '<div class="novel-author">' + novel.author + '</div>' +
        '<div class="novel-progress-bar"><div class="fill" style="width:' + pct + '%"></div></div>' +
        '<div class="novel-progress-text">\u5df2\u8bfb ' + pct + '% \u00b7 \u5171' + total + '\u7ae0</div></div></div>';
    }).join("");
  },

  openNovel(id) {
    const novel = Novels.find(n => n.id === id);
    if (!novel) return;
    this.currentNovel = novel;
    this.renderDetail(novel);
    this.showScreen("screen-detail");
  },

  renderDetail(novel) {
    document.getElementById("detail-title").textContent = novel.title;
    const progress = Storage.getProgress(novel.id);
    const total = novel.chapters.length;
    const chProgress = total > 0 ? ((progress.chapter - 1 + (progress.scrollRatio || 0)) / total) * 100 : 0;
    const pct = chProgress.toFixed(2);
    const bmCount = Storage.getBookmarks(novel.id).length;
    
    document.getElementById("detail-content").innerHTML = 
      '<div class="detail-cover" style="background:' + novel.coverGradient + '">' +
      '<span class="cover-text">' + novel.title + '</span></div>' +
      '<div class="detail-info"><h2>' + novel.title + '</h2>' +
      '<div class="detail-author">' + novel.author + '</div>' +
      '<div class="detail-desc">' + novel.description + '</div></div>' +
      '<div class="detail-stats">' +
      '<div class="stat"><div class="num">' + total + '</div><div class="label">\u7ae0\u8282</div></div>' +
      '<div class="stat"><div class="num">' + pct + '%</div><div class="label">\u5df2\u8bfb</div></div>' +
      '<div class="stat"><div class="num">' + bmCount + '</div><div class="label">\u4e66\u7b7e</div></div>' +
      '</div>';
  },

  startReading() {
    if (!this.currentNovel) return;
    const progress = Storage.getProgress(this.currentNovel.id);
    Reader.open(this.currentNovel, progress.chapter);
  },

  // === CATALOG WITH SEARCH & INFINITE SCROLL ===
  showCatalog(novel) {
    this.showScreen("screen-catalog");
    this.catalogRendered = 0;
    this.catalogNovel = novel;
    this.catalogSearchQuery = "";
    this.catalogSearchResults = null;
    document.getElementById("catalog-list").innerHTML = "";
    document.getElementById("catalog-search-input").value = "";
    document.getElementById("btn-clear-search").style.display = "none";
    this.loadMoreCatalog();
    this.initCatalogScrollbar();
    
    const progress = Storage.getProgress(novel.id);
    const scrollToChapter = () => {
      const el = document.getElementById("cat-ch-" + progress.chapter);
      if (el) {
        el.scrollIntoView({ block: "center" });
      } else if (this.catalogRendered < this.catalogNovel.chapters.length) {
        this.loadMoreCatalog();
        setTimeout(scrollToChapter, 100);
      }
    };
    setTimeout(scrollToChapter, 300);
  },

  loadMoreCatalog() {
    if (this.catalogLoading) return;
    this.catalogLoading = true;
    
    const novel = this.catalogNovel;
    if (!novel) { this.catalogLoading = false; return; }
    
    const source = this.catalogSearchResults || novel.chapters;
    const progress = Storage.getProgress(novel.id);
    const bookmarks = Storage.getBookmarks(novel.id);
    const start = this.catalogRendered;
    const end = Math.min(start + this.catalogBatchSize, source.length);
    
    const list = document.getElementById("catalog-list");
    const frag = document.createDocumentFragment();
    
    for (let i = start; i < end; i++) {
      const ch = source[i];
      const isCurrent = ch.id === progress.chapter;
      const isBookmarked = bookmarks.includes(ch.id);
      const div = document.createElement("div");
      div.id = "cat-ch-" + ch.id;
      div.className = "catalog-item" + (isCurrent ? " current" : "");
      div.onclick = (function(novelId, chapterId) {
        return function() { App.goToChapter(novelId, chapterId); };
      })(novel.id, ch.id);
      div.innerHTML = '<span class="ch-num">\u7b2c' + ch.id + '\u7ae0</span>' +
        '<span class="ch-title">' + ch.title + '</span>' +
        (isBookmarked ? '<span class="ch-read">\ud83d\udcd6</span>' : '') +
        (isCurrent ? '<span class="ch-current-dot"></span>' : '');
      frag.appendChild(div);
    }
    
    list.appendChild(frag);
    this.catalogRendered = end;
    this.catalogLoading = false;
    
    if (end < source.length) {
      const loading = document.createElement("div");
      loading.id = "cat-loading";
      loading.className = "catalog-loading";
      loading.textContent = "\u52a0\u8f7d\u66f4\u591a\u2026";
      list.appendChild(loading);
    }
  },

  initCatalogScrollbar() {
    const list = document.getElementById("catalog-list");
    if (!list) return;
    const screen = document.getElementById("screen-catalog");
    if (!screen) return;

    // Create scrollbar elements once
    let track = document.getElementById("catalog-scrollbar");
    if (!track) {
      track = document.createElement("div");
      track.id = "catalog-scrollbar";
      track.className = "catalog-scrollbar";
      const thumb = document.createElement("div");
      thumb.className = "thumb";
      thumb.id = "catalog-scroll-thumb";
      const label = document.createElement("div");
      label.className = "thumb-label";
      label.id = "catalog-scroll-label";
      thumb.appendChild(label);
      track.appendChild(thumb);
      screen.appendChild(track);
    }

    // Always re-query fresh references
    function getThumb() { return document.getElementById("catalog-scroll-thumb"); }
    function getLabel() { return document.getElementById("catalog-scroll-label"); }
    let t = getThumb();
    if (!t) return;

    // Track position relative to catalog list
    const positionTrack = () => {
      const lr = list.getBoundingClientRect();
      const sr = screen.getBoundingClientRect();
      track.style.top = (lr.top - sr.top) + "px";
      track.style.bottom = (sr.bottom - lr.bottom) + "px";
    };
    positionTrack();
    window.addEventListener("resize", positionTrack);

    // Update thumb position from catalog scroll
    const updateScroll = () => {
      const total = this.catalogSearchResults || (this.catalogNovel ? this.catalogNovel.chapters : null);
      const th = getThumb();
      const lb = getLabel();
      if (!total || total.length === 0 || !th) { if (th) th.style.display = "none"; return; }
      th.style.display = "block";

      const ratio = list.scrollHeight > list.clientHeight
        ? list.scrollTop / (list.scrollHeight - list.clientHeight) : 0;
      const thH = track.clientHeight;
      const thumbH = Math.max(20, Math.min(thH / total.length * 12, thH * 0.4));
      th.style.height = Math.round(thumbH) + "px";
      const maxTop = thH - th.offsetHeight;
      th.style.top = Math.round(ratio * maxTop) + "px";

      const idx = Math.round(ratio * (total.length - 1));
      const ch = total[idx];
      if (ch && lb) lb.textContent = "#" + (ch.id || idx + 1) + " " + (ch.title || "");
    };

    if (list._scrollListener) list.removeEventListener("scroll", list._scrollListener);
    list._scrollListener = updateScroll;
    list.addEventListener("scroll", updateScroll, { passive: true });

    // Drag to jump
    const onDrag = (e) => {
      e.preventDefault();
      const rect = track.getBoundingClientRect();
      const y = (e.touches ? e.touches[0].clientY : e.clientY) - rect.top;
      const total = this.catalogSearchResults || (this.catalogNovel ? this.catalogNovel.chapters : null);
      if (!total || total.length === 0) return;

      const ratio = Math.max(0, Math.min(1, y / rect.height));
      const targetIdx = Math.round(ratio * (total.length - 1));
      const ch = total[targetIdx];

      // Load more if needed
      if (!this.catalogSearchResults) {
        while (this.catalogRendered <= targetIdx && this.catalogRendered < total.length) {
          this.loadMoreCatalog();
        }
      }

      // Scroll to target
      setTimeout(() => {
        const el = document.getElementById("cat-ch-" + (ch ? ch.id : (targetIdx + 1)));
        if (el) el.scrollIntoView({ block: "center" });
        else list.scrollTop = ratio * (list.scrollHeight - list.clientHeight);
      }, 50);

      // Update thumb position and label
      const th = getThumb();
      const lb = getLabel();
      if (th) {
        const thH = track.clientHeight;
        const maxTop = thH - th.offsetHeight;
        th.style.top = Math.round(ratio * maxTop) + "px";
      }
      if (ch && lb) lb.textContent = "#" + (ch.id || targetIdx + 1) + " " + (ch.title || "");
    };

    const onDragEnd = () => {
      document.removeEventListener("mousemove", onDrag);
      document.removeEventListener("mouseup", onDragEnd);
      document.removeEventListener("touchmove", onDrag);
      document.removeEventListener("touchend", onDragEnd);
    };

    const onDragStart = (e) => {
      e.preventDefault();
      document.addEventListener("mousemove", onDrag);
      document.addEventListener("mouseup", onDragEnd);
      document.addEventListener("touchmove", onDrag, { passive: false });
      document.addEventListener("touchend", onDragEnd);
      onDrag(e);
    };

    // Attach drag events (use fresh element ref)
    const freshT = getThumb();
    if (freshT) {
      freshT.onmousedown = null;
      freshT.ontouchstart = null;
      freshT.onmousedown = onDragStart;
      freshT.ontouchstart = onDragStart;
    }

    updateScroll();
  },

  goToChapter(novelId, chapterId) {
    const novel = Novels.find(n => n.id === novelId);
    if (!novel) return;
    this.currentNovel = novel;
    Reader.open(novel, chapterId);
  },

  shareNovel() {
    if (!this.currentNovel) return;
    const data = { title: this.currentNovel.title, text: "\u6211\u6b63\u5728\u8bfb\u300a" + this.currentNovel.title + "\u300b\uff0c\u63a8\u8350\u7ed9\u4f60\uff01", url: location.href };
    if (navigator.share) { navigator.share(data).catch(() => {}); }
    else { navigator.clipboard.writeText(data.text).then(() => this.showToast("\u5df2\u590d\u5236")).catch(() => {}); }
  },

  showToast(msg) {
    const toast = document.getElementById("toast");
    toast.textContent = msg;
    toast.classList.add("show");
    clearTimeout(toast._timeout);
    toast._timeout = setTimeout(() => toast.classList.remove("show"), 2000);
  },

  showInstallBanner() {
    const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
    const isStandalone = window.navigator.standalone;
    if (isIOS && !isStandalone && !Storage.get("install_dismissed")) {
      setTimeout(() => {
        const banner = document.getElementById("install-banner");
        if (banner) banner.style.display = "flex";
      }, 2000);
    }
  }
};

// Scroll + tap to load more chapters
document.addEventListener("DOMContentLoaded", function() {
  var list = document.getElementById("catalog-list");
  if (!list) return;
  
  // Scroll trigger
  list.addEventListener("scroll", function() {
    if (!App.catalogNovel || App.catalogLoading) return;
    var src = App.catalogSearchResults || App.catalogNovel.chapters;
    if (App.catalogRendered >= src.length) return;
    var bottom = list.scrollHeight - list.scrollTop - list.clientHeight;
    if (bottom < 800) App.loadMoreCatalog();
  }, { passive: true });
  
  // Click loading indicator to load more
  list.addEventListener("click", function(e) {
    if (e.target && e.target.id === "cat-loading" && App.catalogNovel && !App.catalogLoading) {
      App.loadMoreCatalog();
    }
  });
});

setInterval(function() {
  if (document.getElementById("screen-reader").classList.contains("active") && Reader.novel) {
    Reader.saveProgress();
  }
}, 3000);

window.addEventListener("beforeunload", function() { if (Reader.novel) Reader.saveProgress(); });
document.addEventListener("DOMContentLoaded", function() { App.init(); });
